#!/bin/bash
# Uninstall script for Nektony App Cleaner & Uninstaller
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Nektony App Cleaner & Uninstaller..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Nektony App Cleaner & Uninstaller if running..."
