echo "Removing /Applications/App Cleaner 10.app..."
if [ -d "/Applications/App Cleaner 10.app" ]; then
    rm -rf "/Applications/App Cleaner 10.app" 2>/dev/null || true
elif [ -f "/Applications/App Cleaner 10.app" ]; then
    rm -f "/Applications/App Cleaner 10.app" 2>/dev/null || true
fi

